ASSET = Path("frontend/assets/houses/items/pool-table.png")
OLD_JPG = Path("frontend/assets/houses/items/pool-table.jpg")
INDEX = Path("frontend/app/(tabs)/index.tsx")

OLD_REQ = "require('../../assets/houses/items/pool-table.jpg')"
NEW_REQ = "require('../../assets/houses/items/pool-table.png')"


def main():
    ASSET.parent.mkdir(parents=True, exist_ok=True)
    ASSET.write_bytes(base64.b64decode(PNG_B64))
    print(f"OK: pool-table.png written ({ASSET.stat().st_size} bytes)")
    if OLD_JPG.exists():
        OLD_JPG.unlink()
        print("OK: old pool-table.jpg removed")
    else:
        print("SKIP: old pool-table.jpg already gone")
    if not INDEX.exists():
        print(f"ERROR: {INDEX} not found. Run from repo root.")
        sys.exit(1)
    src = INDEX.read_text()
    if NEW_REQ in src:
        print("SKIP: pool-table already points to .png")
    elif OLD_REQ in src:
        src = src.replace(OLD_REQ, NEW_REQ)
        INDEX.write_text(src)
        print("OK: pool-table image now points to .png")
    else:
        print("WARNING: pool-table require not found - asset written but reference not updated")
    print("HOUSE_POOL_TABLE_CUTOUT_OK")


if __name__ == "__main__":
    main()
